sn_aia_tool.script:
(function(inputs) {
  var result = { status: 'success', scored_plugins: [] };
  try {
    var plugins = JSON.parse(inputs.outdated_plugins);

    for (var i = 0; i < plugins.length; i++) {
      var plugin = plugins[i];
      var score = 0;
      var factors = [];

      // Security risk factor (0-30 points)
      if (plugin.severity === 'critical') {
        score += 30;
        factors.push('Critical security risk');
      } else {
        score += 15;
        factors.push('Moderate security risk');
      }

      // Dependency chain factor (0-25 points)
      var gr = new GlideRecordSecure('sys_plugins');
      gr.addQuery('active', 'true');
      gr.query();
      var depScore = Math.min(25, gr.getRowCount() > 50 ? 20 : 10);
      score += depScore;
      factors.push('Dependency depth: ' + depScore + '/25');

      // Version age factor (0-25 points)
      var versionParts = (plugin.current_version || '0.0.0').split('.');
      var availParts = (plugin.available_version || '0.0.0').split('.');
      var majorGap = (parseInt(availParts[0], 10) || 0) - (parseInt(versionParts[0], 10) || 0);
      var minorGap = (parseInt(availParts[1], 10) || 0) - (parseInt(versionParts[1], 10) || 0);
      var ageScore = Math.min(25, (majorGap * 15) + (minorGap * 5));
      score += ageScore;
      factors.push('Version age gap: ' + ageScore + '/25');

      // Service mapping impact (0-20 points)
      var impactScore = plugin.severity === 'critical' ? 20 : 10;
      score += impactScore;
      factors.push('Service impact: ' + impactScore + '/20');

      score = Math.min(100, score);

      result.scored_plugins.push({
        sys_id: plugin.sys_id,
        name: plugin.name,
        current_version: plugin.current_version,
        available_version: plugin.available_version,
        priority_score: score,
        priority_tier: score >= 80 ? 'Critical' : score >= 60 ? 'High' : score >= 40 ? 'Medium' : 'Low',
        key_risk_factor: factors[0],
        all_factors: factors
      });
    }

    result.scored_plugins.sort(function(a, b) { return b.priority_score - a.priority_score; });
  } catch (e) {
    result.status = 'error';
    result.message = 'Failed to compute priority scores: ' + e.message;
  }
  return result;
})(inputs);
